<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Support\Str;
class ProjectContract extends Model { protected $fillable=['business_id','branch_id','customer_id','project_number','name','location','contract_amount','paid_amount','payment_mode','status','start_date','completion_date','notes','created_by']; protected static function booted():void{static::creating(fn(self $m)=>$m->public_id??=(string)Str::uuid());} protected function casts():array{return ['contract_amount'=>'decimal:2','paid_amount'=>'decimal:2','start_date'=>'date','completion_date'=>'date'];} public function getRouteKeyName():string{return 'public_id';} public function branch():BelongsTo{return $this->belongsTo(Branch::class);} public function customer():BelongsTo{return $this->belongsTo(Customer::class);} public function requests():HasMany{return $this->hasMany(ProjectPaymentRequest::class);} public function payments():HasMany{return $this->hasMany(ProjectPayment::class);} public function materialIssues():HasMany{return $this->hasMany(ProjectMaterialIssue::class);} }
